script:
(function () {
  'use strict';
  // 2026 federal income tax estimate following the Form 1040 flow:
  //   total income (wages, interest, dividends, capital gain/loss, self-employment, retirement,
  //     taxable Social Security, other) - adjustments (IRA, HSA, half SE tax, student loan
  //     interest, other) = AGI
  //   AGI - larger of standard deduction (+ non-itemizer cash charity) or itemized deductions
  //     - Schedule 1-A deductions (tips, overtime, car loan interest, senior) - QBI deduction
  //     = taxable income
  //   Tax: ordinary brackets, with qualified dividends and net long-term gains stacked on top at
  //     0/15/20% (Qualified Dividends and Capital Gain Tax Worksheet).
  //   - child tax credit / credit for other dependents and other nonrefundable credits
  //   + self-employment tax + 0.9% Additional Medicare tax + 3.8% net investment income tax
  //   = total tax; payments = withholding + estimated payments + Additional Medicare withheld
  //     on wages over $200,000 + additional child tax credit + earned income credit
  //     + other refundable credits. Refund or amount owed = payments - total tax.
  // Not modeled: alternative minimum tax, QBI wage/property limits above the threshold,
  //   capital loss carryovers, kiddie tax, foreign income, and credits other than CTC/ODC/EITC.
  // Verified (Node, scratch tests, each against an independent hand calculation):
  //   Single, $75,000 wages, $8,000 withheld -> taxable $58,900, tax $7,670.00, refund $330.00
  //     (matches take-home-paycheck-calculator). MFJ $100,000, 2 children -> taxable $67,800,
  //     tax $7,640 - $4,400 credit = $3,240.00.
  //   HOH $25,000 wages, 1 child -> tax $85 wiped out by the credit, ACTC $1,700,
  //     EITC $4,249.62 ($4,427 - 15.98% x $1,110); IRS tables use $50 bands, so +/- a few dollars.
  //   Single $40,000 wages + $10,000 qualified dividends -> $2,620.00 (dividends in the 0% band);
  //     $80,000 wages + $20,000 long-term gain -> $11,770.00 ($8,770 + 15% x $20,000).
  //   Single, $30,000 Social Security + $20,000 pension -> $5,350 taxable (Pub. 915 worksheet).
  //   $50,000 self-employment profit -> SE tax $7,064.78, QBI deduction $6,073.52 (taxable-income
  //     limit), taxable $24,294.09, total tax $9,732.07.
  //   Single $700,000 wages + $50,000 interest, $60,000 SALT, $20,000 mortgage, $10,000 charity ->
  //     SALT cap $10,000 (floor), itemized $34,290.54 after the 2/37 cut, tax $220,769.75,
  //     Additional Medicare $4,500, NIIT $1,900.
  //   Single $60,000 wages, 65+, $10,000 tips, $5,000 overtime, $2,000 car interest ->
  //     Schedule 1-A $23,000, taxable $18,850, tax $2,014.00.
  //   Bracket table and capital gains breakpoints are the same constants as take-home-paycheck-
  //     calculator and tax-harvesting (checked against Rev. Proc. 2025-32).
  //
  // ---- 2026 FEDERAL CONSTANTS (tax year 2026) -------------------------------------------
  // Brackets, standard deductions, additional 65+/blind amounts, capital gains breakpoints,
  //   child tax credit ($2,200; $1,700 refundable), EITC table and $12,200 investment income
  //   limit, student loan interest phase-out, QBI threshold: IRS Rev. Proc. 2025-32 (as amended
  //   by P.L. 119-21), sections 4.01, 4.03, 4.05, 4.06, 4.14, 4.26, 4.29.
  // Tips, overtime, car loan interest and senior deductions (amounts, phase-outs and rounding):
  //   Schedule 1-A (Form 1040); IRS newsroom "One Big Beautiful Bill Act: tax deductions for
  //   working Americans and seniors". Not available to married filing separately (except car loan).
  // SALT cap $40,400 ($20,200 MFS), reduced by 30% of AGI over $505,000 ($252,500 MFS):
  //   draft 2026 Schedule A line 5e; $10,000 ($5,000 MFS) floor: IRC 164(b)(7).
  // Charity: 0.5%-of-AGI floor for itemizers, $1,000/$2,000 non-itemizer cash deduction, and the
  //   2/37 itemized deduction reduction above the 37% bracket: Form 1040-ES (2026), IRC 68.
  // QBI minimum deduction $400 when QBI is at least $1,000: IRC 199A(i), Rev. Proc. 2025-32 s. 3.12.
  // Social Security wage base $184,500: Form 1040-ES (2026), SSA. SE tax 15.3% on 92.35% of
  //   profit: IRC 1401, 1402. Additional Medicare 0.9% and NIIT 3.8% thresholds are statutory
  //   (IRC 3101(b)(2), 1411) and not indexed. Social Security benefit base amounts: IRC 86.
  var TAX_YEAR = 2026;
  var KEY = { single: 'single', mfj: 'mfj', mfs: 'mfs', hoh: 'hoh', qss: 'mfj' }; // QSS uses joint brackets
  var BRACKETS = { // upper limit of each band; rates 10, 12, 22, 24, 32, 35, 37%
    single: [12400, 50400, 105700, 201775, 256225, 640600],
    mfj:    [24800, 100800, 211400, 403550, 512450, 768700],
    mfs:    [12400, 50400, 105700, 201775, 256225, 384350],
    hoh:    [17700, 67450, 105700, 201750, 256200, 640600]
  };
  var RATES = [0.10, 0.12, 0.22, 0.24, 0.32, 0.35, 0.37];
  var CG_BREAKS = { single: [49450, 545500], mfj: [98900, 613700], hoh: [66200, 579600], mfs: [49450, 306850] };
  var STANDARD_DEDUCTION = { single: 16100, mfj: 32200, mfs: 16100, hoh: 24150, qss: 32200 };
  var ADDITIONAL_STD = { single: 2050, hoh: 2050, mfj: 1650, mfs: 1650, qss: 1650 }; // per 65+ or blind
  var LOSS_LIMIT = { single: 3000, mfj: 3000, hoh: 3000, mfs: 1500, qss: 3000 };
  var CHILD_CREDIT = 2200, CHILD_REFUNDABLE = 1700, OTHER_DEPENDENT_CREDIT = 500;
  var CTC_PHASEOUT = { single: 200000, hoh: 200000, mfs: 200000, mfj: 400000, qss: 200000 };
  var ACTC_EARNED_FLOOR = 2500, ACTC_RATE = 0.15;
  var EITC = { // by qualifying children 0..3: credit rate, earned income amount, phase-out rate,
               // phase-out start (other / joint)
    rate: [0.0765, 0.34, 0.40, 0.45], earned: [8680, 13020, 18290, 18290], max: [664, 4427, 7316, 8231],
    phaseRate: [0.0765, 0.1598, 0.2106, 0.2106],
    start: [10860, 23890, 23890, 23890], startJoint: [18140, 31160, 31160, 31160]
  };
  var EITC_INVESTMENT_LIMIT = 12200;
  var STUDENT_LOAN_MAX = 2500;
  var STUDENT_LOAN_PHASE = { single: [85000, 100000], hoh: [85000, 100000], qss: [85000, 100000], mfj: [175000, 205000] };
  var TIPS_MAX = 25000, OVERTIME_MAX = { mfj: 25000, other: 12500 }, TIP_OT_PHASE = { mfj: 300000, other: 150000 };
  var CAR_MAX = 10000, CAR_PHASE = { mfj: 200000, other: 100000 };
  var SENIOR_DEDUCTION = 6000, SENIOR_PHASE = { mfj: 150000, other: 75000 }, SENIOR_RATE = 0.06;
  var SALT_CAP = { single: 40400, mfj: 40400, hoh: 40400, qss: 40400, mfs: 20200 };
  var SALT_PHASE = { single: 505000, mfj: 505000, hoh: 505000, qss: 505000, mfs: 252500 };
  var SALT_FLOOR = { single: 10000, mfj: 10000, hoh: 10000, qss: 10000, mfs: 5000 };
  var MEDICAL_FLOOR = 0.075, CHARITY_FLOOR = 0.005;
  var NONITEMIZER_CHARITY = { mfj: 2000, other: 1000 };
  var QBI_RATE = 0.20, QBI_MIN = 400, QBI_MIN_INCOME = 1000;
  var QBI_THRESHOLD = { single: 201750, hoh: 201750, qss: 201750, mfs: 201775, mfj: 403500 };
  var SS_WAGE_BASE = 184500, SE_FACTOR = 0.9235, SE_SS = 0.124, SE_MED = 0.029;
  var ADDL_MED_RATE = 0.009, ADDL_MED = { mfj: 250000, mfs: 125000, other: 200000 };
  var NIIT_RATE = 0.038, NIIT = { mfj: 250000, qss: 250000, mfs: 125000, other: 200000 };
  var SS_BASE = { single: [25000, 34000], hoh: [25000, 34000], qss: [25000, 34000], mfj: [32000, 44000], mfs: [0, 0] };
  // ---------------------------------------------------------------------------------------

  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  var whole = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });

  function pick(map, status) { return map[status] !== undefined ? map[status] : map.other; }

  function ordinaryTax(income, key) {
    var limits = BRACKETS[key], tax = 0, lower = 0;
    for (var i = 0; i < RATES.length; i++) {
      var upper = i < limits.length ? limits[i] : Infinity;
      if (income > lower) tax += (Math.min(income, upper) - lower) * RATES[i];
      lower = upper;
    }
    return tax;
  }
  function marginalRate(income, key) {
    var limits = BRACKETS[key];
    for (var i = 0; i < limits.length; i++) if (income <= limits[i]) return RATES[i];
    return RATES[RATES.length - 1];
  }

  // Qualified Dividends and Capital Gain Tax Worksheet.
  function incomeTax(taxable, pref, key) {
    var gains = Math.max(0, Math.min(pref, taxable)), base = taxable - gains, b = CG_BREAKS[key];
    var mid = Math.max(0, Math.min(taxable, b[1]) - Math.max(base, b[0]));
    var top = Math.max(0, taxable - Math.max(base, b[1]));
    return { tax: Math.min(ordinaryTax(base, key) + 0.15 * mid + 0.20 * top, ordinaryTax(taxable, key)), ordinary: base };
  }

  function taxableSocialSecurity(benefits, otherIncome, status) {
    if (benefits <= 0) return 0;
    var prov = otherIncome + 0.5 * benefits, b = SS_BASE[status];
    if (status === 'mfs') return Math.min(0.85 * benefits, 0.85 * Math.max(0, prov));
    var over1 = prov - b[0];
    if (over1 <= 0) return 0;
    var tier1 = Math.min(over1, b[1] - b[0]);
    var over2 = Math.max(0, prov - b[1]);
    return Math.min(Math.min(0.5 * tier1, 0.5 * benefits) + 0.85 * over2, 0.85 * benefits);
  }

  function eitcAmount(n, x, joint) {
    var cap = EITC.max[n];
    var start = joint ? EITC.startJoint[n] : EITC.start[n];
    return Math.max(0, Math.min(EITC.rate[n] * x, cap) - EITC.phaseRate[n] * Math.max(0, x - start));
  }

  function compute(o) {
    var s = o.status, key = KEY[s], joint = s === 'mfj';
    // Self-employment tax (Schedule SE)
    var nese = Math.max(0, o.selfEmp) * SE_FACTOR;
    if (nese < 400) nese = 0;
    var seTax = SE_SS * Math.min(nese, Math.max(0, SS_WAGE_BASE - o.wages)) + SE_MED * nese;
    var halfSe = seTax / 2;
    // Capital gains and losses (Schedule D)
    var netCap = o.shortGain + o.longGain;
    var capIncluded = netCap >= 0 ? netCap : -Math.min(-netCap, LOSS_LIMIT[s]);
    var netLtGain = netCap > 0 ? Math.max(0, Math.min(o.longGain, netCap)) : 0;
    var qualDiv = Math.min(o.qualDiv, o.dividends);
    // Income and adjustments
    var incomeExSs = o.wages + o.interest + o.dividends + capIncluded + o.selfEmp + o.retire + o.otherInc;
    var adjExSl = o.ira + o.hsa + halfSe + o.otherAdj;
    var taxableSs = taxableSocialSecurity(o.socSec, incomeExSs - adjExSl + o.taxExempt, s);
    var totalIncome = incomeExSs + taxableSs;
    var agiBeforeSl = totalIncome - adjExSl;
    var sl = 0;
    if (s !== 'mfs' && o.studentLoan > 0) {
      var ph = STUDENT_LOAN_PHASE[s];
      var share = Math.min(1, Math.max(0, (agiBeforeSl - ph[0]) / (ph[1] - ph[0])));
      sl = Math.min(o.studentLoan, STUDENT_LOAN_MAX) * (1 - share);
    }
    var adjustments = adjExSl + sl;
    var agi = totalIncome - adjustments;
    var agiPos = Math.max(0, agi);

    // Standard deduction vs itemized (Schedule A)
    var extraCount = (o.you65 ? 1 : 0) + (o.youBlind ? 1 : 0) +
                     (joint || s === 'mfs' ? (o.spouse65 ? 1 : 0) + (o.spouseBlind ? 1 : 0) : 0);
    var standard = STANDARD_DEDUCTION[s] + extraCount * ADDITIONAL_STD[s];
    var nonItemCharity = Math.min(o.charityCash, pick(NONITEMIZER_CHARITY, s));
    var saltCap = Math.max(SALT_FLOOR[s], SALT_CAP[s] - 0.30 * Math.max(0, agi - SALT_PHASE[s]));
    var salt = Math.min(o.salt, saltCap);
    var medical = Math.max(0, o.medical - MEDICAL_FLOOR * agiPos);
    var charity = Math.max(0, o.charityCash + o.charityNonCash - CHARITY_FLOOR * agiPos);
    var itemizedRaw = medical + salt + o.mortgage + charity + o.otherItem;
    var top = BRACKETS[key][BRACKETS[key].length - 1];
    var itemized = itemizedRaw - (2 / 37) * Math.min(itemizedRaw, Math.max(0, agi - top));
    var itemize = itemized > standard + nonItemCharity;
    var deduction = itemize ? itemized : standard + nonItemCharity;

    // Schedule 1-A
    var tips = 0, overtime = 0, car = 0, senior = 0, over;
    if (s !== 'mfs') {
      over = Math.max(0, agi - pick(TIP_OT_PHASE, s));
      var cut = Math.floor(over / 1000) * 100;
      tips = Math.max(0, Math.min(o.tips, TIPS_MAX) - cut);
      overtime = Math.max(0, Math.min(o.overtime, pick(OVERTIME_MAX, s)) - cut);
      var seniors = (o.you65 ? 1 : 0) + (joint && o.spouse65 ? 1 : 0);
      senior = seniors * Math.max(0, SENIOR_DEDUCTION - SENIOR_RATE * Math.max(0, agi - pick(SENIOR_PHASE, s)));
    }
    over = Math.max(0, agi - pick(CAR_PHASE, s));
    car = Math.max(0, Math.min(o.carInterest, CAR_MAX) - Math.ceil(over / 1000) * 200);
    var schedule1a = tips + overtime + car + senior;

    // Qualified business income deduction (simplified, Form 8995)
    var pref = qualDiv + netLtGain;
    var beforeQbi = Math.max(0, agi - deduction - schedule1a);
    var qbiIncome = Math.max(0, o.selfEmp) - halfSe;
    var qbi = 0;
    if (qbiIncome > 0) {
      qbi = Math.min(QBI_RATE * qbiIncome, QBI_RATE * Math.max(0, beforeQbi - pref));
      if (qbiIncome >= QBI_MIN_INCOME) qbi = Math.max(qbi, Math.min(QBI_MIN, beforeQbi));
    }
    var taxable = Math.max(0, beforeQbi - qbi);
    var it = incomeTax(taxable, pref, key);

    // Credits (Schedule 8812) and nonrefundable credits
    var ctcTotal = o.kids * CHILD_CREDIT + o.otherDeps * OTHER_DEPENDENT_CREDIT;
    ctcTotal = Math.max(0, ctcTotal - Math.ceil(Math.max(0, agi - CTC_PHASEOUT[s]) / 1000) * 50);
    var ctcUsed = Math.min(ctcTotal, it.tax);
    var otherCredits = Math.min(o.otherCredits, it.tax - ctcUsed);
    var taxAfterCredits = it.tax - ctcUsed - otherCredits;
    var earned = o.wages + Math.max(0, nese > 0 ? o.selfEmp - halfSe : 0);
    var actc = o.kids > 0 ? Math.max(0, Math.min(ctcTotal - ctcUsed, o.kids * CHILD_REFUNDABLE,
                                               ACTC_RATE * Math.max(0, earned - ACTC_EARNED_FLOOR))) : 0;
    var eitc = 0, invIncome = o.interest + o.dividends + o.taxExempt + Math.max(0, netCap);
    if (o.eitcOn && s !== 'mfs' && invIncome <= EITC_INVESTMENT_LIMIT && earned > 0) {
      var n = Math.min(3, o.kids);
      eitc = eitcAmount(n, earned, joint);
      var start = joint ? EITC.startJoint[n] : EITC.start[n];
      if (agi >= start) eitc = Math.min(eitc, eitcAmount(n, Math.max(0, agi), joint));
    }

    // Other taxes (Schedule 2)
    var addlMed = ADDL_MED_RATE * Math.max(0, o.wages + nese - pick(ADDL_MED, s));
    var addlMedWithheld = ADDL_MED_RATE * Math.max(0, o.wages - 200000);
    var nii = Math.max(0, o.interest + o.dividends + capIncluded);
    var niit = NIIT_RATE * Math.min(nii, Math.max(0, agi - pick(NIIT, s)));
    var totalTax = taxAfterCredits + seTax + addlMed + niit;
    var payments = o.withheld + o.estimated + addlMedWithheld + actc + eitc + o.refundable;

    return {
      wages: o.wages, interest: o.interest, dividends: o.dividends, capIncluded: capIncluded, selfEmp: o.selfEmp,
      retire: o.retire, taxableSs: taxableSs, otherInc: o.otherInc, totalIncome: totalIncome,
      adjustments: adjustments, halfSe: halfSe, sl: sl, agi: agi, standard: standard, nonItemCharity: nonItemCharity,
      itemized: itemized, itemize: itemize, deduction: deduction, saltCap: saltCap, schedule1a: schedule1a,
      tips: tips, overtime: overtime, car: car, senior: senior, qbi: qbi, taxable: taxable, pref: pref,
      ordinaryIncome: it.ordinary, tax: it.tax, ctcUsed: ctcUsed, otherCredits: otherCredits,
      taxAfterCredits: taxAfterCredits, seTax: seTax, addlMed: addlMed, niit: niit, totalTax: totalTax,
      withheld: o.withheld, estimated: o.estimated, addlMedWithheld: addlMedWithheld, actc: actc, eitc: eitc,
      refundable: o.refundable, payments: payments, balance: payments - totalTax,
      marginal: marginalRate(Math.max(0, it.ordinary), key), key: key
    };
  }

  // ---- page wiring ----------------------------------------------------------------------
  var FIELDS = {
    wages: 'itWages', withheld: 'itWithheld', kids: 'itKids', otherDeps: 'itOtherDeps', interest: 'itInterest',
    dividends: 'itDividends', qualDiv: 'itQualDiv', taxExempt: 'itTaxExempt', shortGain: 'itShortGain',
    longGain: 'itLongGain', selfEmp: 'itSelfEmp', retire: 'itRetire', socSec: 'itSocSec', otherInc: 'itOtherInc',
    ira: 'itIra', hsa: 'itHsa', studentLoan: 'itStudentLoan', otherAdj: 'itOtherAdj', tips: 'itTips',
    overtime: 'itOvertime', carInterest: 'itCarInterest', medical: 'itMedical', salt: 'itSalt', mortgage: 'itMortgage',
    otherItem: 'itOtherItem', charityCash: 'itCharityCash', charityNonCash: 'itCharityNonCash',
    estimated: 'itEstimated', otherCredits: 'itOtherCredits', refundable: 'itRefundable'
  };
  var SIGNED = { shortGain: true, longGain: true };

  function readNum(id) {
    var el = document.getElementById(id);
    if (!el || el.value === '') return 0;
    var v = parseFloat(el.value);
    return isNaN(v) ? NaN : v;
  }
  function isChecked(id) { var el = document.getElementById(id); return !!(el && el.checked); }
  function set(id, text) { var el = document.getElementById(id); if (el) el.textContent = text; }
  function signed(v) { return v < -0.005 ? '−' + money.format(-v) : money.format(Math.max(0, v)); }
  function minus(v) { return v > 0.005 ? '−' + money.format(v) : money.format(0); }

  function fillTable(id, rows) {
    var body = document.getElementById(id);
    if (!body) return;
    while (body.firstChild) body.removeChild(body.firstChild);
    rows.forEach(function (cells) {
      var tr = document.createElement('tr');
      cells.forEach(function (t, i) {
        var td = document.createElement(i === 0 ? 'th' : 'td');
        if (i === 0) td.setAttribute('scope', 'row');
        td.textContent = t;
        tr.appendChild(td);
      });
      body.appendChild(tr);
    });
  }

  function clear() {
    ['itResult', 'itTotalTax', 'itTaxable', 'itAgi', 'itDeduction', 'itMarginal', 'itEffective', 'itPayments']
      .forEach(function (id) { set(id, '–'); });
    set('itResultLabel', 'Estimated refund');
    fillTable('itBreakdown', []);
    fillTable('itBrackets', []);
    var note = document.getElementById('itNote');
    if (note) note.hidden = true;
  }

  function update() {
    var statusEl = document.getElementById('itStatus');
    var o = { status: statusEl && KEY[statusEl.value] ? statusEl.value : 'single' };
    var msg = '';
    Object.keys(FIELDS).forEach(function (k) {
      var v = readNum(FIELDS[k]);
      if (!isFinite(v) || Math.abs(v) > 1e10) msg = msg || 'Enter numbers only. Leave a field at 0 if it does not apply.';
      else if (v < 0 && !SIGNED[k]) msg = msg || 'Only capital gains can be negative. Enter the other amounts as 0 or more.';
      o[k] = v;
    });
    if (!msg && (o.kids > 20 || o.otherDeps > 20 || Math.round(o.kids) !== o.kids || Math.round(o.otherDeps) !== o.otherDeps)) {
      msg = 'Enter the number of children and dependents as whole numbers up to 20.';
    }
    if (!msg && o.qualDiv > o.dividends) msg = 'Qualified dividends are part of ordinary dividends, so they cannot be larger.';
    var error = document.getElementById('itError');
    if (error) { error.hidden = !msg; error.textContent = msg; }
    if (msg) { clear(); return; }
    o.you65 = isChecked('itYou65'); o.youBlind = isChecked('itYouBlind');
    o.spouse65 = isChecked('itSpouse65'); o.spouseBlind = isChecked('itSpouseBlind');
    o.eitcOn = isChecked('itEitc');

    var r = compute(o);
    var refund = r.balance >= 0;
    set('itResultLabel', refund ? 'Estimated refund' : 'Estimated amount you owe');
    set('itResult', money.format(Math.abs(r.balance)));
    set('itTotalTax', money.format(r.totalTax));
    set('itTaxable', money.format(r.taxable));
    set('itAgi', signed(r.agi));
    set('itDeduction', (r.itemize ? 'Itemized ' : 'Standard ') + money.format(r.deduction));
    set('itMarginal', Math.round(r.marginal * 100) + '%');
    set('itEffective', r.totalIncome > 0 ? (r.totalTax / r.totalIncome * 100).toFixed(1) + '%' : '0.0%');
    set('itPayments', money.format(r.payments));

    var rows = [
      ['Wages, salaries and tips', money.format(r.wages)],
      ['Interest and ordinary dividends', money.format(r.interest + r.dividends)],
      ['Capital gain or (allowed loss)', signed(r.capIncluded)],
      ['Self-employment profit', money.format(r.selfEmp)],
      ['IRA, pension and annuity income', money.format(r.retire)],
      ['Taxable Social Security', money.format(r.taxableSs)],
      ['Other income', money.format(r.otherInc)],
      ['Total income', signed(r.totalIncome)],
      ['Adjustments to income (incl. half of SE tax)', minus(r.adjustments)],
      ['Adjusted gross income', signed(r.agi)],
      [(r.itemize ? 'Itemized deductions' : 'Standard deduction' + (r.nonItemCharity > 0 ? ' + cash charity' : '')), minus(r.deduction)],
      ['Tips, overtime, car loan and senior deductions', minus(r.schedule1a)],
      ['Qualified business income deduction', minus(r.qbi)],
      ['Taxable income', money.format(r.taxable)],
      ['Income tax', money.format(r.tax)],
      ['Child and other dependent credit', minus(r.ctcUsed)],
      ['Other nonrefundable credits', minus(r.otherCredits)],
      ['Self-employment tax', money.format(r.seTax)],
      ['Additional Medicare tax', money.format(r.addlMed)],
      ['Net investment income tax', money.format(r.niit)],
      ['Total tax', money.format(r.totalTax)],
      ['Federal income tax withheld', money.format(r.withheld)],
      ['Estimated tax payments', money.format(r.estimated)],
      ['Additional Medicare tax withheld by employer', money.format(r.addlMedWithheld)],
      ['Earned income credit', money.format(r.eitc)],
      ['Additional child tax credit (refundable)', money.format(r.actc)],
      ['Other refundable credits', money.format(r.refundable)],
      ['Total payments and refundable credits', money.format(r.payments)],
      [refund ? 'Refund' : 'Amount you owe', money.format(Math.abs(r.balance))]
    ];
    fillTable('itBreakdown', rows);

    var limits = BRACKETS[r.key], lower = 0, brows = [];
    for (var i = 0; i < RATES.length; i++) {
      var upper = i < limits.length ? limits[i] : Infinity;
      var amt = Math.max(0, Math.min(r.ordinaryIncome, upper) - lower);
      brows.push([Math.round(RATES[i] * 100) + '%',
                  isFinite(upper) ? whole.format(lower) + ' – ' + whole.format(upper) : 'Over ' + whole.format(lower),
                  money.format(amt), money.format(amt * RATES[i])]);
      lower = upper;
    }
    fillTable('itBrackets', brows);

    var notes = [];
    if (r.itemize) notes.push('Your itemized deductions are larger than your ' + whole.format(r.standard) + ' standard deduction, so they are used.');
    if (o.salt > r.saltCap) notes.push('State and local taxes are capped at ' + whole.format(r.saltCap) + ' for your income.');
    if (o.status === 'mfs' && (o.tips > 0 || o.overtime > 0)) notes.push('The tips and overtime deductions require a joint return if you are married.');
    if ((o.spouse65 || o.spouseBlind) && o.status !== 'mfj' && o.status !== 'mfs') notes.push('Spouse boxes only apply to married filing statuses.');
    if (o.status === 'mfs' && (o.spouse65 || o.spouseBlind)) notes.push('When filing separately, the spouse amounts count only if your spouse has no income and cannot be claimed by someone else.');
    if (o.selfEmp > 0 && r.taxable > QBI_THRESHOLD[o.status]) notes.push('Your taxable income is above the ' + whole.format(QBI_THRESHOLD[o.status]) + ' QBI threshold, where wage and property limits can shrink the business income deduction shown here.');
    if (!refund && -r.balance >= 1000) notes.push('Owing $1,000 or more can mean an underpayment penalty unless your withholding and estimated payments meet a safe harbor.');
    var note = document.getElementById('itNote');
    if (note) { note.hidden = notes.length === 0; note.textContent = notes.join(' '); }
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('itForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
